function deleteTx(id){let t=db.transactions.find(x=>x.id===id);if(!t)return;modal('Delete this transaction?',`<p class="section-sub" style="line-height:1.6">Remove <b>${esc(t.description)}</b> (${fmt(t.amount)}) from your ledger? Your balance and budgets will update.</p><div class="modal-actions"><button class="secondary-btn" data-close>Keep it</button><button class="primary-btn" id="confirm-delete" style="background:var(--red);color:#260b0c">Delete transaction</button></div>`);$('#confirm-delete').onclick=()=>{db.transactions=db.transactions.filter(x=>x.id!==id);save();closeModal();render();showToast('Transaction deleted.')}}
function budgetModal(name){let value=name?db.budgets[name]:'';modal(name?'Edit category budget':'Add category budget',`<form id="budget-form"><div class="form-grid"><div class="form-field ${name?'full':''}"><label>Category</label><input name="category" ${name?'readonly':''} required maxlength="40" value="${esc(name||'')}" placeholder="e.g. Books & supplies"></div><div class="form-field ${name?'full':''}"><label>Monthly limit (₹)</label><input name="amount" type="number" min="0" step="0.01" required value="${value}" placeholder="1000"></div></div><div class="modal-actions"><button type="button" class="secondary-btn" data-close>Cancel</button><button class="primary-btn">Save budget</button></div></form>`);$('#budget-form').onsubmit=e=>{e.preventDefault();let d=Object.fromEntries(new FormData(e.currentTarget)),v=Number(d.amount),c=d.category.trim();if(!c||!Number.isFinite(v)||v<0)return showToast('Enter a category and a valid non-negative limit.');db.budgets[c]=v;save();closeModal();render();showToast('Budget saved.')}}
function rollBalanceOnce(){let el=$('.balance-number');if(!el)return;let value=balance().toLocaleString('en-IN',{minimumFractionDigits:2,maximumFractionDigits:2}),column=0;el.innerHTML='<em>₹</em>'+value.split('').map(char=>{if(!/\d/.test(char))return `<span class="slot-punctuation">${char}</span>`;let digit=Number(char),turns=3+(column%2),landing=turns*10+digit,delay=column*65,duration=1180+(column%3)*100,index=column++,cells=Array.from({length:landing+1},(_,n)=>n===landing?digit:(n*7+index*3+n%4)%10).map(n=>`<i>${n}</i>`).join('');return `<span class="slot-window"><span class="slot-strip" style="--from:0em;--to:-${landing}em;--roll-ms:${duration}ms;--wait:${delay}ms">${cells}</span></span>`}).join('')}function messNudge(){let favorites=(db.messFavorites||[]).map(x=>x.toLowerCase()),menu=(db.messTodayMenu||'').split(',').map(x=>x.trim());let match=menu.find(item=>item&&favorites.some(food=>item.toLowerCase().includes(food)||food.includes(item.toLowerCase())));return match?`<div class="mess-nudge reveal"><span class="mess-spark">✳</span><div><b>Plot twist: the mess is covering your craving.</b><small>${esc(match)} is on today. Your wallet gets to sit this one out.</small></div><span class="mess-tag">MESSIT MATCH</span></div>`:''}
function drawChart(){let c=$('#flow-chart');if(!c)return;let r=c.getBoundingClientRect(),dpr=devicePixelRatio||1;c.width=r.width*dpr;c.height=r.height*dpr;let x=c.getContext('2d');x.scale(dpr,dpr);let w=r.width,h=r.height,days=14,arr=Array.from({length:days},(_,i)=>{let d=new Date();d.setDate(d.getDate()-(days-1-i));let k=dateISO(d);return {key:k,label:d.getDate(),income:sum(db.transactions.filter(t=>t.date===k),'income'),expense:sum(db.transactions.filter(t=>t.date===k),'expense')}}),max=Math.max(1,...arr.flatMap(a=>[a.income,a.expense])),pad={l:5,r:5,t:9,b:20},usable=h-pad.t-pad.b,slot=(w-pad.l-pad.r)/days;x.strokeStyle='#282d39';for(let j=0;j<3;j++){let y=pad.t+usable*j/2;x.beginPath();x.moveTo(0,y);x.lineTo(w,y);x.stroke()}arr.forEach((a,i)=>{let cx=pad.l+slot*i+slot/2,bw=Math.max(3,slot*.2),v1=a.income/max*usable,v2=a.expense/max*usable;x.fillStyle=getComputedStyle(document.body).getPropertyValue('--accent').trim()||'#c7f36b';x.beginPath();x.roundRect(cx-bw-1,pad.t+usable-v1,bw,v1,3);x.fill();x.fillStyle='#a594ff';x.beginPath();x.roundRect(cx+1,pad.t+usable-v2,bw,v2,3);x.fill();if(i%2===0||i===13){x.fillStyle='#737c8f';x.font='9px DM Mono';x.textAlign='center';x.fillText(a.label,cx,h-4)}})}
function simulate(){let amount=Number($('#sim-amount')?.value),category=$('#sim-category')?.value,name=$('#sim-name')?.value||'This purchase',box=$('#sim-result');if(!amount||amount<=0)return showToast('Enter a price greater than zero.');let post=balance()-amount,catLeft=Number(db.budgets[category]||0)-spentCategory(category),fits=post>=0&&catLeft>=amount;box.innerHTML=`<div class="eyebrow">THE HONEST PREVIEW</div><div class="verdict ${fits?'good':'bad'}">${fits?'Possible, with room to think.':'This would stretch your plan.'}</div><div class="safe-desc">${esc(name)} would leave about</div><div class="sim-amount ${moneyClass()}">${fmt(post)}</div><div class="safe-desc">tracked balance · ${catLeft>=amount?fmt(catLeft-amount)+' left in '+esc(category):fmt(Math.max(0,amount-catLeft))+' beyond your '+esc(category)+' budget'}<br><br>Estimate uses today’s ledger and category budget. It doesn’t account for unrecorded bills or create a transaction.</div>`}
function exportCsv(){let rows=[['id','date','type','amount','description','category','payment','recurring','notes'],...txs().map(t=>[t.id,t.date,t.type,t.amount,t.description,t.category,t.payment||'',t.recurring?'true':'false',t.notes||''])],csv=rows.map(r=>r.map(v=>'"'+String(v??'').replaceAll('"','""')+'"').join(',')).join('\r\n'),a=document.createElement('a');a.href=URL.createObjectURL(new Blob(['\uFEFF'+csv],{type:'text/csv'}));a.download='paisa-transactions-'+today()+'.csv';a.click();URL.revokeObjectURL(a.href);showToast('CSV exported.')}
function parseCSV(text){let rows=[],row=[],v='',q=false;for(let i=0;i<text.length;i++){let c=text[i];if(q&&c==='"'&&text[i+1]==='"'){v+='"';i++}else if(c==='"')q=!q;else if(c===','&&!q){row.push(v);v=''}else if((c==='\n'||c==='\r')&&!q){if(c==='\r'&&text[i+1]==='\n')i++;row.push(v);if(row.some(x=>x.trim()))rows.push(row);row=[];v=''}else v+=c}row.push(v);if(row.some(x=>x.trim()))rows.push(row);return rows}
function suggestCategory(s){s=s.toLowerCase();if(/swiggy|zomato|food delivery/.test(s))return 'Food delivery';if(/chai|canteen|mess|maggi|snack/.test(s))return 'Food & snacks';if(/auto|uber|ola|metro|bus|cab/.test(s))return 'Transport';if(/print|stationery|book|college/.test(s))return 'College & printing';if(/netflix|spotify|prime|subscription/.test(s))return 'Subscriptions';return 'Miscellaneous'}
async function importCsv(file){try{let rows=parseCSV(await file.text());if(rows.length<2)throw Error('This CSV has no transaction rows.');let heads=rows[0].map(x=>x.trim().toLowerCase()),idx=(...names)=>heads.findIndex(h=>names.some(n=>h===n||h.includes(n))),di=idx('date'),ai=idx('amount'),debi=idx('debit'),ci=idx('credit'),desc=idx('description','merchant','details','narration'),cat=idx('category'),type=idx('type');if(di<0||(ai<0&&debi<0&&ci<0))throw Error('Could not identify a date and amount column. Add headings such as Date, Amount, Description.');let parsed=[],bad=0,dupes=0;for(let r of rows.slice(1)){let rawDate=String(r[di]||'').trim(),d=new Date(rawDate);if(!rawDate||Number.isNaN(d.getTime())){bad++;continue}let raw=ai>=0?String(r[ai]||'').replace(/[₹,\s]/g,''):String(r[debi]||'').replace(/[₹,\s]/g,'')||String(r[ci]||'').replace(/[₹,\s]/g,''),amount=Math.abs(Number(raw));if(!Number.isFinite(amount)||amount<=0){bad++;continue}let description=desc>=0?r[desc].trim():'Imported transaction',ttype=type>=0&&/income|credit/i.test(r[type])?'income':ai<0&&ci>=0&&String(r[ci]).trim()?'income':Number(String(r[ai]||'').replace(/[₹,\s]/g,''))<0?'income':'expense';if(db.transactions.some(x=>x.date===dateISO(d)&&Number(x.amount)===amount&&x.description.toLowerCase()===description.toLowerCase()&&x.type===ttype)){dupes++;continue}parsed.push({date:dateISO(d),amount,type:ttype,description:description||'Imported transaction',category:cat>=0&&r[cat].trim()?r[cat].trim():suggestCategory(description),payment:'',recurring:false,notes:'Imported CSV',id:crypto.randomUUID(),created:new Date().toISOString()})}if(!parsed.length)throw Error(`No new valid rows. ${bad} invalid, ${dupes} likely duplicate(s).`);modal('Review CSV import',`<div class="note">${parsed.length} valid transactions ready · ${bad} invalid row(s) skipped · ${dupes} likely duplicate(s) skipped.<br>Review preview before importing. No entries are saved until confirmed.</div><div style="max-height:220px;overflow:auto;margin-top:10px">${parsed.slice(0,6).map(t=>`<div class="setting-row"><span>${esc(t.date)} · ${esc(t.description)}<small>${esc(t.category)} · ${t.type}</small></span><b>${fmt(t.amount)}</b></div>`).join('')}${parsed.length>6?`<div class="subline">and ${parsed.length-6} more…</div>`:''}</div><div class="modal-actions"><button class="secondary-btn" data-close>Cancel</button><button class="primary-btn" id="confirm-import">Import ${parsed.length}</button></div>`);$('#confirm-import').onclick=()=>{db.transactions.push(...parsed);save();closeModal();go('transactions');showToast(`${parsed.length} transactions imported.`)}}catch(e){showToast(e.message||'Could not read this CSV.')}}
function firstRun(){if(db.onboarded||session)return;modal('Welcome to Paisa.exe',`<p class="section-sub" style="line-height:1.7">Your money has a story. Unfortunately, some chapters are titled “late-night cravings.” Let’s set a starting point. You can change these numbers later; nothing is sent anywhere.</p><form id="setup-form"><div class="form-grid"><div class="form-field"><label>Current starting balance (₹)</label><input name="opening" type="number" min="0" step="0.01" value="${Number(db.openingBalance)}"></div><div class="form-field"><label>Expected monthly income (₹)</label><input name="income" type="number" min="0" step="0.01" value="${Number(db.monthlyIncome)}"></div></div><div class="modal-actions"><button type="button" class="secondary-btn" id="explore-demo">Explore empty ledger</button><button class="primary-btn">Save & get started</button></div></form>`);$('#setup-form').onsubmit=e=>{e.preventDefault();let d=Object.fromEntries(new FormData(e.currentTarget)),o=Number(d.opening),i=Number(d.income);if(o<0||i<0||!Number.isFinite(o+i))return showToast('Enter valid non-negative amounts.');db.openingBalance=o;db.monthlyIncome=i;db.onboarded=true;save();closeModal();render()};$('#explore-demo').onclick=()=>{db.onboarded=true;save();closeModal();render();showToast('Empty ledger ready. Add real transactions when you’re ready.')}}
